   while(true) {
     // Wait until we have been notified 20 times before running the code
     if(task_notify_take(false, TIMEOUT_MAX) == 20) {
       // ... Code to do stuff here ...

       // Reset the notification counter
       task_notify_take(true, TIMEOUT_MAX);
     }
     delay(10);
 	 }
 }

