 	 task_t task = task_create(my_task_fn, NULL, TASK_PRIORITY_DEFAULT,
 						   TASK_STACK_DEPTH_DEFAULT, "My Task");

   int count = 0;

   while(true) {
     if(controller_get_digital(CONTROLLER_MASTER, DIGITAL_L1)) {
       task_notify_ext(task, 1, NOTIFY_ACTION_INCREMENT, &count);
     }

     delay(20);
   }
 }
```

