 while (true) {
   vision_object_s_t rtn = vision_get_by_sig(VISION_PORT, 0, EXAMPLE_SIG);
   // Gets the largest object of the EXAMPLE_SIG signature
   printf("sig: %d", rtn.signature);
   // Prints "sig: 1"
   delay(2);
   }
 }
