   while(true) {
     std::optional<pros::MutexVar<Pose>> cur_pose_opt = odom_pose.try_lock(100);

     if(cur_pose_opt.has_value()) {
       Pose* cur_pose = **cur_pose_opt;
     }
     else {
       printf("Could not lock the mutex var!");
     }

     pros::delay(10);
   }
 }
