     delay(2);
   }
 }
```

Reads up to object_count object descriptors into object_arr.

### Parameters

- `size_id`: The object to read from a list roughly ordered by object size (0 is the largest item, 1 is the second largest, etc.)
- `object_count`: The number of objects to read
- `object_arr`: A pointer to copy the objects into

### Errors

- `ENODEV`: The port cannot be configured as a vision sensor
- `EDOM`: size_id is greater than the number of available objects.
- `EAGAIN`: Reading the vision sensor failed for an unknown reason.

### Returns

The number of object signatures copied. This number will be less than object_count if there are fewer objects detected by the vision sensor. Returns PROS_ERR if the port was invalid, an error occurred, or fewer objects than size_id were found. All objects in object_arr that were not found are given VISION_OBJECT_ERR_SIG as their signature.

### Example

```cpp
 #define VISION_PORT 1
 #define NUM_VISION_OBJECTS 4

 void opcontrol() {
   pros::Vision vision_sensor(VISION_PORT);
   vision_object_s_t object_arr[NUM_VISION_OBJECTS];
   while (true) {
     vision_sensor.read_by_size(0, NUM_VISION_OBJECTS, object_arr);
     printf("sig: %d", object_arr[0].signature);
     // Prints the signature of the largest object found
     delay(2);
   }
 }
```

Sets the exposure parameter of the Vision Sensor.

### Parameters

- `percent`: The new exposure setting from [0,150].

### Errors

- `ENODEV`: The port cannot be configured as a vision sensor

### Returns

1 if the operation was successful or PROS_ERR if the operation failed, setting errno.

### Example

```cpp
 #define VISION_PORT 1

 void initialize() {
 	 pros::Vision vision_sensor(VISION_PORT);
   if (vision_sensor.get_exposure() < 50)
   vision_sensor.set_exposure(50);
 }
```

Creates a signature from the vision sensor utility

### Parameters

- `id`: The signature ID
- `u_min`: Minimum value on U axis
- `u_max`: Maximum value on U axis
- `u_mean`: Mean value on U axis
- `v_min`: Minimum value on V axis
- `v_max`: Maximum value on V axis
- `v_mean`: Mean value on V axis
- `rgb`: Scale factor
- `type`: Signature type

### Returns

A vision_signature_s_t that can be set using Vision::set_signature

### Example

```cpp
 #define VISION_PORT 1
 #define EXAMPLE_SIG 1

 void opcontrol() {
 pros::Vision vision_sensor(VISION_PORT);
 // values acquired from the vision utility
 vision_signature_s_t RED_SIG =
   vision_signature_from_utility(EXAMPLE_SIG, 8973, 11143, 10058, -2119, -1053, -1586, 5.4, 0);
 vision_sensor.set_signature(EXAMPLE_SIG, &RED_SIG);
 while (true) {
   vision_signature_s_t rtn = vision_sensor.get_by_sig(VISION_PORT, 0, EXAMPLE_SIG);
   // Gets the largest object of the EXAMPLE_SIG signature
   printf("sig: %d", rtn.signature);
   // Prints "sig: 1"
   delay(2);
   }
 }
```
